def build_order(steps, deps):
    out = {s: [] for s in steps}
    indeg = {s: 0 for s in steps}
    for a, b in deps:
        out[a].append(b)
        indeg[b] += 1
    q = deque(s for s in steps if indeg[s] == 0)
    order = []
    while q:
        v = q.popleft()
        order.append(v)
        for w in out[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                q.append(w)
    return order

