def suffix_array(s):
    n = len(s)
    sa, rk, k = list(range(n)), [ord(c) for c in s], 1
    if n <= 1:
        return sa
    while True:
        key = [(rk[i], rk[i + k] if i + k < n else 0) for i in range(n)]
        sa.sort(key=key.__getitem__)
        nr = [0] * n
        for t in range(1, n):
            nr[sa[t]] = nr[sa[t - 1]] + (key[sa[t]] != key[sa[t - 1]])
        rk = nr
        if rk[sa[-1]] == n - 1 or k >= n:
            return sa
        k *= 2

